INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('3d0446ee-8b69-7a84-bade-12fe67f2de53', '3d040005-0000-0000-0000-000000000003', 'Indoxacarb 200ml/acre (Helicoverpa Pod Borer control at Flowering)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('4e1557ff-9c7a-8b95-cbef-230f78f3ef64', '4e150006-0000-0000-0000-000000000001', 'Pendimethalin 1L/acre Pre-emergence Herbicide (Weed control at Sowing)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('4e1557ff-9c7a-8b95-cbef-230f78f3ef64', '4e150006-0000-0000-0000-000000000003', 'Mancozeb 75% WP 30g/pump (Tikka Leaf Spot Fungicide at Flowering/Pegging)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('4e1557ff-9c7a-8b95-cbef-230f78f3ef64', '4e150006-0000-0000-0000-000000000003', 'Imidacloprid 0.5ml/liter (Aphids & Thrips control)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('5f2668aa-bd8b-9ca6-dcf0-341a89f4f075', '5f260007-0000-0000-0000-000000000001', 'Pendimethalin 1L/200L water (Pre-emergence Weed control Day 1 after transplanting)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('5f2668aa-bd8b-9ca6-dcf0-341a89f4f075', '5f260007-0000-0000-0000-000000000003', 'Lambda-cyhalothrin 5 EC 10ml/pump (Thrips & Aphid control at Bulb Initiation)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('5f2668aa-bd8b-9ca6-dcf0-341a89f4f075', '5f260007-0000-0000-0000-000000000004', 'Mancozeb 30g/pump (Purple Blotch / Blight Fungicide at Bulb Development)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('6a3779bb-ce9c-ad07-edf1-452b90f50186', '6a370008-0000-0000-0000-000000000002', 'Yellow Sticky Traps 10-15/acre (Whitefly/Aphid monitoring from Day 25)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('6a3779bb-ce9c-ad07-edf1-452b90f50186', '6a370008-0000-0000-0000-000000000003', 'Chlorantraniliprole (Coragen) 0.3ml/liter (Fruit Borer control at Flowering)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('6a3779bb-ce9c-ad07-edf1-452b90f50186', '6a370008-0000-0000-0000-000000000004', 'Acetamiprid 20 SP 100g/acre (Whitefly/Aphid control at Fruiting)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('6a3779bb-ce9c-ad07-edf1-452b90f50186', '6a370008-0000-0000-0000-000000000004', 'Mancozeb 25g/pump (Blight Fungicide Prevention at Fruiting Stage)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('7b4880cc-dfad-be18-fef2-563c01f61297', '7b480009-0000-0000-0000-000000000002', 'Emamectin Benzoate 5% SG 100g/acre (Fall Armyworm control into whorl)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('7b4880cc-dfad-be18-fef2-563c01f61297', '7b480009-0000-0000-0000-000000000003', 'Propiconazole 1ml/liter (Rust & Leaf Blight Fungicide at Flowering)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('8c5991dd-e0be-cf29-0fa3-674d12f723a8', '8c590010-0000-0000-0000-000000000001', 'Metalaxyl 35% SD 6g/kg Seed Treatment (Downy Mildew prevention at Sowing)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('8c5991dd-e0be-cf29-0fa3-674d12f723a8', '8c590010-0000-0000-0000-000000000002', 'Atrazine 50 WP 400g/acre (Pre-emergence Weed control at Day 15-20)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('9d6002ee-f1cf-d03a-1ab4-785e23f834b9', '9d600011-0000-0000-0000-000000000001', 'Thiram/Carbendazim 3g/kg Seed Treatment (Soil-borne disease prevention)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('9d6002ee-f1cf-d03a-1ab4-785e23f834b9', '9d600011-0000-0000-0000-000000000002', 'Cypermethrin 25% EC 100ml/acre (Shoot Fly & Stem Borer control)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('9d6002ee-f1cf-d03a-1ab4-785e23f834b9', '9d600011-0000-0000-0000-000000000003', 'Emamectin Benzoate 100g/acre (Stem Borer control at Flowering if infestation high)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('ae7113ff-02df-e14b-2bc5-896f34f945ca', 'ae710012-0000-0000-0000-000000000002', 'Gibberellic Acid GA3 25 ppm (Berry Thinning at Full Bloom)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('ae7113ff-02df-e14b-2bc5-896f34f945ca', 'ae710012-0000-0000-0000-000000000003', 'Carbendazim + Sulfur (Powdery Mildew Preventive Fungicide at Berry Development)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('ae7113ff-02df-e14b-2bc5-896f34f945ca', 'ae710012-0000-0000-0000-000000000003', 'Imidacloprid 0.5ml/liter (Thrips & Mealybug control at Berry Development)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('bf8224aa-13e0-f25c-3cd6-9a7f45a056db', 'bf820013-0000-0000-0000-000000000001', 'Copper Oxychloride 2.5g/L (Bacterial Blight Prevention 7-10 day interval after Pruning)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('bf8224aa-13e0-f25c-3cd6-9a7f45a056db', 'bf820013-0000-0000-0000-000000000003', 'Neem Oil 3% (Pomegranate Butterfly preventive spray during Fruit Development)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('bf8224aa-13e0-f25c-3cd6-9a7f45a056db', 'bf820013-0000-0000-0000-000000000004', 'Azadirachtin 1% 3ml/L (Monthly Preventive Insecticide at Fruit Maturity)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('c09335bb-24f1-036d-4de7-ab8f56b167ec', 'c0930014-0000-0000-0000-000000000002', 'Hexaconazole / Sulfur (Powdery Mildew Preventive Fungicide before Flowering)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('c09335bb-24f1-036d-4de7-ab8f56b167ec', 'c0930014-0000-0000-0000-000000000002', 'Imidacloprid (Mango Hoppers & Thrips control at Vegetative Flush)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('c09335bb-24f1-036d-4de7-ab8f56b167ec', 'c0930014-0000-0000-0000-000000000003', 'Methyl Eugenol Traps 10-12/acre (Mango Fruit Fly monitoring from April-September)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('d10446cc-3502-147e-5ef8-bc9f67c278ed', 'd1040015-0000-0000-0000-000000000002', 'Imidacloprid 0.5ml/L (Aphid control - Aphids spread Banana Bunchy Top Virus)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('d10446cc-3502-147e-5ef8-bc9f67c278ed', 'd1040015-0000-0000-0000-000000000003', 'Copper Oxychloride (Leaf Spot/Sigatoka Preventive Fungicide - cover underside of leaves)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('d10446cc-3502-147e-5ef8-bc9f67c278ed', 'd1040015-0000-0000-0000-000000000004', 'Chlorpyrifos Drenching (Rhizome/Pseudostem Weevil soil drenching at Fruiting)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('e21557dd-4613-258f-6f09-cd0f78d389fe', 'e2150016-0000-0000-0000-000000000001', 'Pendimethalin 800ml/acre (Pre-emergence Weed Control within 2-3 days of planting)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('e21557dd-4613-258f-6f09-cd0f78d389fe', 'e2150016-0000-0000-0000-000000000002', 'Acephate 75 SP 600g/100L water (Rhizome Fly/Borer control at Vegetative Stage)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('e21557dd-4613-258f-6f09-cd0f78d389fe', 'e2150016-0000-0000-0000-000000000003', 'Mancozeb 0.3% (Leaf Blotch/Spot Fungicide at Rhizome Initiation Stage)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('f32668ee-5724-369f-7f1a-de1f89e49aff', 'f3260017-0000-0000-0000-000000000001', 'Mancozeb 3g/L Rhizome Treatment (Seed rhizome dip 30 min before planting to prevent rot)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('f32668ee-5724-369f-7f1a-de1f89e49aff', 'f3260017-0000-0000-0000-000000000002', 'Neem Oil 0.5% (Shoot Borer prevention spray at fortnightly intervals July to October)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('f32668ee-5724-369f-7f1a-de1f89e49aff', 'f3260017-0000-0000-0000-000000000003', 'Chlorpyriphos 0.075% soil drenching (Rhizome Soft Rot prevention if symptoms appear)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('043779ff-6835-47af-8f2b-ef2f9af50b00', '04370018-0000-0000-0000-000000000001', 'Yellow & Blue Sticky Traps (Thrips/Aphid/Whitefly monitoring from Day 1)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('043779ff-6835-47af-8f2b-ef2f9af50b00', '04370018-0000-0000-0000-000000000003', 'Imidacloprid or Fipronil (Thrips/Mites/Aphid control at Flowering)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('043779ff-6835-47af-8f2b-ef2f9af50b00', '04370018-0000-0000-0000-000000000004', 'Chlorpyrifos / Azadirachtin (Fruit Borer control at Fruiting Stage)');
INSERT INTO spray_schedule (crop_master_id, stage_id, spray_name) VALUES ('043779ff-6835-47af-8f2b-ef2f9af50b00', '04370018-0000-0000-0000-000000000004', 'Copper-based Fungicide (Fruit Rot / Leaf Spot prevention at Fruiting Stage)');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('f99617d1-e63d-4c8d-8fe0-cbb1fa0d7ff3', 'f9910001-0000-0000-0000-000000000002', 'Most Critical: First irrigation at Crown Root Initiation (Day 20-25) for tiller development. 50mm required.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('f99617d1-e63d-4c8d-8fe0-cbb1fa0d7ff3', 'f9910001-0000-0000-0000-000000000003', 'Irrigation at Flowering/Ear Emergence (Day 65-70). 40mm required.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('f99617d1-e63d-4c8d-8fe0-cbb1fa0d7ff3', 'f9910001-0000-0000-0000-000000000004', 'Irrigation at Grain Filling (Day 90-95). Avoid irrigation 15 days before harvest.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('0a7114bb-5e36-4d51-87ab-89cd34efab20', '0a110002-0000-0000-0000-000000000001', 'Maintain shallow standing water (2-3 cm) after transplanting for weed suppression.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('0a7114bb-5e36-4d51-87ab-89cd34efab20', '0a110002-0000-0000-0000-000000000002', 'Standing water 2-3 cm during Tillering phase for optimal tiller production.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('0a7114bb-5e36-4d51-87ab-89cd34efab20', '0a110002-0000-0000-0000-000000000003', 'Critical Stage: Increase water level to 5 cm from Panicle Initiation until 10 days before harvest.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('1b8224cc-6f47-5e62-98bc-90de45f0bc31', '1b820003-0000-0000-0000-000000000002', 'Avoid water stress during Tillering. Drip irrigation recommended. Irrigate every 8-10 days.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('1b8224cc-6f47-5e62-98bc-90de45f0bc31', '1b820003-0000-0000-0000-000000000003', 'Regular irrigation every 7-10 days during Grand Growth Phase. Critical for cane elongation.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('1b8224cc-6f47-5e62-98bc-90de45f0bc31', '1b820003-0000-0000-0000-000000000004', 'Reduce irrigation at Maturation Phase to increase sugar content. Stop 30 days before harvest.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('2c9335dd-7a58-6f73-a9cd-01ef56f1cd42', '2c930004-0000-0000-0000-000000000003', 'Provide protective irrigation during dry spells at Flowering & Pod Setting. Tur is sensitive to waterlogging.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('2c9335dd-7a58-6f73-a9cd-01ef56f1cd42', '2c930004-0000-0000-0000-000000000004', 'Stop irrigation 15-20 days before harvest. Ensure good drainage at all times.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('3d0446ee-8b69-7a84-bade-12fe67f2de53', '3d040005-0000-0000-0000-000000000003', 'Light protective irrigation at Flowering if no rainfall for 10+ days. Avoid waterlogging.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('3d0446ee-8b69-7a84-bade-12fe67f2de53', '3d040005-0000-0000-0000-000000000004', 'Light irrigation if needed at Pod Filling. Stop irrigation 2 weeks before harvest.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('4e1557ff-9c7a-8b95-cbef-230f78f3ef64', '4e150006-0000-0000-0000-000000000002', 'Avoid irrigation for ~25 days after establishment to synchronize flowering.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('4e1557ff-9c7a-8b95-cbef-230f78f3ef64', '4e150006-0000-0000-0000-000000000003', 'Critical Stage: Irrigate at Flowering & Peg Penetration (Day 40-45) for pod development.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('4e1557ff-9c7a-8b95-cbef-230f78f3ef64', '4e150006-0000-0000-0000-000000000004', 'Maintain soil moisture during Pod Development. Last irrigation at Day 90-95. Stop before harvest.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('5f2668aa-bd8b-9ca6-dcf0-341a89f4f075', '5f260007-0000-0000-0000-000000000002', 'Drip irrigation recommended. Irrigate every 5-7 days at Vegetative Stage.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('5f2668aa-bd8b-9ca6-dcf0-341a89f4f075', '5f260007-0000-0000-0000-000000000003', 'Critical Stage: Maintain consistent moisture at Bulb Initiation (Day 40-60). Do not over-water.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('5f2668aa-bd8b-9ca6-dcf0-341a89f4f075', '5f260007-0000-0000-0000-000000000005', 'Stop irrigation 15 days before harvest when foliage turns yellow/brown.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('6a3779bb-ce9c-ad07-edf1-452b90f50186', '6a370008-0000-0000-0000-000000000001', 'Drip irrigation recommended from the start. Ensure good drainage - waterlogging causes disease.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('6a3779bb-ce9c-ad07-edf1-452b90f50186', '6a370008-0000-0000-0000-000000000003', 'Critical: Avoid water stress at Flowering. Consistent moisture for proper fruit set.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('6a3779bb-ce9c-ad07-edf1-452b90f50186', '6a370008-0000-0000-0000-000000000004', 'Uniform moisture at Fruiting stage to prevent blossom end rot. Drip irrigation ideal.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('7b4880cc-dfad-be18-fef2-563c01f61297', '7b480009-0000-0000-0000-000000000003', 'Most Critical Stage: Avoid water stress at Flowering & Tasseling. Ensure irrigation if rain is absent.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('7b4880cc-dfad-be18-fef2-563c01f61297', '7b480009-0000-0000-0000-000000000004', 'Maintain soil moisture during Grain Filling. Reduce irrigation as crop approaches maturity.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('8c5991dd-e0be-cf29-0fa3-674d12f723a8', '8c590010-0000-0000-0000-000000000003', 'Irrigate at Flowering stage if rainfall is inadequate. Bajra is drought-tolerant but benefits here.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('8c5991dd-e0be-cf29-0fa3-674d12f723a8', '8c590010-0000-0000-0000-000000000004', 'Light irrigation at Grain Filling if needed. Stop irrigation as crop nears maturity.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('9d6002ee-f1cf-d03a-1ab4-785e23f834b9', '9d600011-0000-0000-0000-000000000003', 'Irrigate at Flowering stage if rainfall is insufficient. Critical for grain yield.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('9d6002ee-f1cf-d03a-1ab4-785e23f834b9', '9d600011-0000-0000-0000-000000000004', 'Maintain moisture at Grain Filling. Stop irrigation 15 days before harvest.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('ae7113ff-02df-e14b-2bc5-896f34f945ca', 'ae710012-0000-0000-0000-000000000001', 'Drip irrigation essential. Begin moderate watering at Bud Break. Adjust based on soil moisture.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('ae7113ff-02df-e14b-2bc5-896f34f945ca', 'ae710012-0000-0000-0000-000000000003', 'Regular drip irrigation at Berry Development. Avoid waterlogging which causes disease.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('ae7113ff-02df-e14b-2bc5-896f34f945ca', 'ae710012-0000-0000-0000-000000000004', 'Reduce irrigation at Ripening Stage. Excess moisture can dilute sugar and cause disease.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('bf8224aa-13e0-f25c-3cd6-9a7f45a056db', 'bf820013-0000-0000-0000-000000000001', 'Drip irrigation recommended. Ensure perfect drainage. Avoid waterlogging at all stages.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('bf8224aa-13e0-f25c-3cd6-9a7f45a056db', 'bf820013-0000-0000-0000-000000000003', 'Consistent moisture during Fruit Development for uniform size. Drip at 2-3 day intervals.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('bf8224aa-13e0-f25c-3cd6-9a7f45a056db', 'bf820013-0000-0000-0000-000000000004', 'Reduce water at Fruit Maturity to improve taste and color. Stop 10 days before harvest.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('c09335bb-24f1-036d-4de7-ab8f56b167ec', 'c0930014-0000-0000-0000-000000000001', 'Avoid irrigation 2-3 months before expected flowering to induce dry stress for better blossom.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('c09335bb-24f1-036d-4de7-ab8f56b167ec', 'c0930014-0000-0000-0000-000000000003', 'Begin irrigation after fruit set. Drip irrigation every 3-5 days during Fruit Development.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('c09335bb-24f1-036d-4de7-ab8f56b167ec', 'c0930014-0000-0000-0000-000000000004', 'Reduce irrigation at Fruit Maturity. Stop 15 days before harvest for better fruit quality.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('d10446cc-3502-147e-5ef8-bc9f67c278ed', 'd1040015-0000-0000-0000-000000000001', 'Drip irrigation mandatory. 8-10 liters per plant per day at Establishment Stage.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('d10446cc-3502-147e-5ef8-bc9f67c278ed', 'd1040015-0000-0000-0000-000000000002', 'High water demand during Vegetative Growth. 15-20 liters per plant per day via drip.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('d10446cc-3502-147e-5ef8-bc9f67c278ed', 'd1040015-0000-0000-0000-000000000004', 'Consistent drip irrigation at Flowering & Fruiting for bunch development. Avoid drought stress.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('e21557dd-4613-258f-6f09-cd0f78d389fe', 'e2150016-0000-0000-0000-000000000001', 'Irrigate immediately after planting. Mulch with green leaves to retain moisture. Avoid waterlogging.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('e21557dd-4613-258f-6f09-cd0f78d389fe', 'e2150016-0000-0000-0000-000000000003', 'Maintain consistent moisture at Rhizome Initiation. Drip irrigation every 8-10 days.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('e21557dd-4613-258f-6f09-cd0f78d389fe', 'e2150016-0000-0000-0000-000000000004', 'Reduce irrigation at Maturity Stage. Harvest when leaves turn yellow and dry.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('f32668ee-5724-369f-7f1a-de1f89e49aff', 'f3260017-0000-0000-0000-000000000001', 'Mulch immediately after planting with green leaves to retain soil moisture.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('f32668ee-5724-369f-7f1a-de1f89e49aff', 'f3260017-0000-0000-0000-000000000002', 'Light irrigation every 10-15 days if not rainfed. Avoid waterlogging at all costs to prevent rot.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('f32668ee-5724-369f-7f1a-de1f89e49aff', 'f3260017-0000-0000-0000-000000000003', 'Maintain moisture during Rhizome Development. Reduce watering 30 days before harvest.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('043779ff-6835-47af-8f2b-ef2f9af50b00', '04370018-0000-0000-0000-000000000001', 'Drip irrigation + Plastic mulching recommended. Irrigate every 5-7 days at Establishment.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('043779ff-6835-47af-8f2b-ef2f9af50b00', '04370018-0000-0000-0000-000000000003', 'Critical: Consistent moisture at Flowering & Fruit Set. Water stress causes flower/fruit drop.');
INSERT INTO irrigation_schedule (crop_master_id, stage_id, water_requirement) VALUES ('043779ff-6835-47af-8f2b-ef2f9af50b00', '04370018-0000-0000-0000-000000000004', 'Regular drip irrigation at Fruiting Stage. Reduce irrigation as final harvest approaches.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('f99617d1-e63d-4c8d-8fe0-cbb1fa0d7ff3', 'Yellow Rust (पिवळा गंज)', 'Yellow stripes/pustules on leaves parallel to leaf veins.', 'Spray Propiconazole (Tilt) 1ml/L or Tebuconazole 1ml/L as soon as symptoms appear.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('0a7114bb-5e36-4d51-87ab-89cd34efab20', 'Blast Disease (भात करपा)', 'Diamond shaped lesions with grey center and brown border on leaves and neck.', 'Spray Tricyclazole 75 WP 120g/acre at first symptom. Repeat after 15 days if needed.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('0a7114bb-5e36-4d51-87ab-89cd34efab20', 'Sheath Blight (आवरण करपा)', 'Oval/irregular greenish-grey lesions on leaf sheaths near water level.', 'Spray Validamycin or Hexaconazole 5 SC 400ml/acre when 25% tillers are infected.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('1b8224cc-6f47-5e62-98bc-90de45f0bc31', 'Red Rot (लाल सड)', 'Internal red staining with white spots on cross-section of stalk.', 'Use healthy certified setts. Treat setts with Carbendazim 1g/L for 15 minutes before planting.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('2c9335dd-7a58-6f73-a9cd-01ef56f1cd42', 'Sterility Mosaic (बांझपण मोझाईक)', 'Infected plants show mosaic yellow-green mottling and remain sterile - no pods formed.', 'No cure. Remove and destroy infected plants immediately. Control mite vectors with Dicofol spray.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('3d0446ee-8b69-7a84-bade-12fe67f2de53', 'Fusarium Wilt (मान मोडी / उकाडा)', 'Plants wilt suddenly turning pale green then yellow. Root shows brown discoloration.', 'Use resistant varieties. Seed treatment with Trichoderma viride 6g/kg + Carbendazim 2g/kg.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('4e1557ff-9c7a-8b95-cbef-230f78f3ef64', 'Tikka Leaf Spot (तिका पानकरपा)', 'Dark brown circular spots with yellow halo on leaves leading to early defoliation.', 'Spray Mancozeb 75% WP 30g per pump or Chlorothalonil 2g/L at first sign.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('5f2668aa-bd8b-9ca6-dcf0-341a89f4f075', 'Purple Blotch (जांभळा डाग रोग)', 'Small white lesions with purple center on leaves leading to dieback.', 'Spray Mancozeb 2.5g/L or Iprodione 1.5g/L at 7-10 day intervals during humid weather.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('6a3779bb-ce9c-ad07-edf1-452b90f50186', 'Early Blight (आगोदर करपा)', 'Dark brown concentric ring spots (target board pattern) on older leaves.', 'Spray Mancozeb + Metalaxyl 2.5g/L or Azoxystrobin 1ml/L at first symptom.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('7b4880cc-dfad-be18-fef2-563c01f61297', 'Northern Leaf Blight (पाने करपा)', 'Long grey-green lesions on leaves that turn tan as they mature.', 'Spray Mancozeb 2g/L or Propiconazole 1ml/L when disease appears.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('ae7113ff-02df-e14b-2bc5-896f34f945ca', 'Powdery Mildew (भुकटी बुरशी)', 'White powdery coating on leaves shoots and berries. Berries may crack.', 'Spray Sulfur 80 WP 3g/L or Myclobutanil 1g/L. Maintain good canopy aeration.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('bf8224aa-13e0-f25c-3cd6-9a7f45a056db', 'Bacterial Blight (जीवाणूजन्य करपा)', 'Water-soaked spots on leaves/fruits turning dark brown/black leading to fruit cracking and drop.', 'Spray Copper Oxychloride 2.5g/L at 7-10 day intervals. Rotate with Bronopol 0.5g/L + Captan 3g/L.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('c09335bb-24f1-036d-4de7-ab8f56b167ec', 'Powdery Mildew (भुकटी बुरशी)', 'White powdery growth on inflorescence and young fruits causing flower/fruit drop.', 'Spray Sulfur 80% WP 3g/L or Hexaconazole 1ml/L at first symptom during flowering.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('d10446cc-3502-147e-5ef8-bc9f67c278ed', 'Sigatoka Leaf Spot (सिगाटोका पानावरील डाग)', 'Yellow streaks on youngest leaves progressing to dark brown necrotic spots.', 'Spray Mancozeb 2g/L or Propiconazole 1ml/L. Ensure thorough coverage of leaf underside.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('e21557dd-4613-258f-6f09-cd0f78d389fe', 'Leaf Blotch (पान करपा)', 'Brown rectangular spots on leaves often with yellow border leading to drying.', 'Spray Mancozeb 0.25% or Copper Oxychloride 0.3% at first sign of infection.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('f32668ee-5724-369f-7f1a-de1f89e49aff', 'Soft Rot / Rhizome Rot (मऊ सड)', 'Yellowing of lower leaves wilting soft water-soaked lesions on rhizomes.', 'Ensure perfect drainage. Soil drench with Metalaxyl + Mancozeb. Remove and destroy infected plants.');
INSERT INTO diseases (crop_master_id, name, symptoms, treatment) VALUES ('043779ff-6835-47af-8f2b-ef2f9af50b00', 'Anthracnose / Fruit Rot (फळ सड)', 'Dark sunken lesions on fruits with concentric rings. Infected fruits shrivel and drop.', 'Spray Copper Hydroxide or Mancozeb 2g/L. Use resistant varieties. Avoid excess moisture.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('f99617d1-e63d-4c8d-8fe0-cbb1fa0d7ff3', 'Aphid (माव)', 'Small soft-bodied insects on leaves and ears causing yellowing and honeydew secretion.', 'Spray Dimethoate 30 EC 1.5ml/L or Thiamethoxam 25 WG 0.2g/L when colonies are seen.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('0a7114bb-5e36-4d51-87ab-89cd34efab20', 'Brown Plant Hopper (तपकिरी तुडतुडा)', 'Hopper burn - circular burnt patches in field. Insects cluster at base of plants.', 'Spray Pymetrozine 50 WG 0.3g/L or Buprofezin 25 SC 1ml/L. Avoid synthetic pyrethroids.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('1b8224cc-6f47-5e62-98bc-90de45f0bc31', 'Early Shoot Borer (खोड किडा)', 'Dead heart in young plants. Affected shoots emit foul smell when pulled.', 'Release Trichogramma egg parasitoids. Spray Chlorantraniliprole 18.5 SC 0.3ml/L if ETL crossed.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('2c9335dd-7a58-6f73-a9cd-01ef56f1cd42', 'Tur Pod Borer / Helicoverpa (बोंडअळी)', 'Circular holes in pods. Damaged seeds with larval frass inside pods.', 'Install Pheromone traps 5/acre. Spray HaNPV 450 LE/acre or Indoxacarb 14.5 SC 200ml/acre.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('3d0446ee-8b69-7a84-bade-12fe67f2de53', 'Gram Pod Borer / Helicoverpa (हरभरा बोंडअळी)', 'Larva eats from inside pod. Circular holes in pods. Half-eaten seeds visible.', 'Pheromone traps 5-6/hectare. Spray HaNPV at first sign. Indoxacarb at ETL crossing.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('4e1557ff-9c7a-8b95-cbef-230f78f3ef64', 'Leaf Miner (पान खाणारी अळी)', 'Serpentine mines (white tunnels) visible on leaves from larval feeding.', 'Spray Fipronil 5 SC 1ml/L or Imidacloprid 0.5ml/L when mines are first noticed.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('5f2668aa-bd8b-9ca6-dcf0-341a89f4f075', 'Onion Thrips (फुलकिडे)', 'Silvery streaks on leaves curling of leaves deformed bulbs. Stunted plant growth.', 'Spray Spinosad 2.5 SC 1ml/L or Lambda-cyhalothrin 5 EC 1ml/L. Use blue sticky traps.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('6a3779bb-ce9c-ad07-edf1-452b90f50186', 'Tomato Fruit Borer (फळ पोखरणारी अळी)', 'Pin holes on green fruits. Caterpillar feeds inside fruit. Rotting of fruits follows.', 'Pheromone traps 10/acre. Spray Chlorantraniliprole 0.3ml/L or Emamectin Benzoate 0.4g/L.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('7b4880cc-dfad-be18-fef2-563c01f61297', 'Fall Armyworm (लष्करी अळी)', 'Ragged holes in leaves and whorl. Frass in whorl. Pin holes on cobs.', 'Spray Emamectin Benzoate 5% SG 100g/acre or Chlorantraniliprole 18.5 SC into the whorl at ETL.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('8c5991dd-e0be-cf29-0fa3-674d12f723a8', 'Shoot Fly (खोड माशी)', 'Dead heart symptom in young seedlings. Central leaf wilts and dries.', 'Early sowing in recommended window. Treat seeds with Thiamethoxam 70 WS 2g/kg. Remove dead hearts.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('9d6002ee-f1cf-d03a-1ab4-785e23f834b9', 'Stem Borer (खोड किडा)', 'Dead heart in young plants. Small entry holes in stem. Wilting of central shoot.', 'Early sowing. Spray Cypermethrin 25% EC 100ml/acre when infestation exceeds economic threshold.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('ae7113ff-02df-e14b-2bc5-896f34f945ca', 'Mealybug (पांढरी माव)', 'White waxy cottony clusters on stems and bunches. Honeydew secretion causing sooty mold.', 'Spray Chlorpyrifos 20 EC 2ml/L or use Profenophos for severe infestations. Maintain orchard hygiene.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('bf8224aa-13e0-f25c-3cd6-9a7f45a056db', 'Pomegranate Butterfly (डाळिंब फुलपाखरू)', 'Larvae bore into developing fruits causing premature fruit drop and internal damage.', 'Individual fruit bagging after marble stage. Neem Oil 3% spray. Remove and destroy affected fruits.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('c09335bb-24f1-036d-4de7-ab8f56b167ec', 'Mango Hopper (आंबा तुडतुडा)', 'Nymphs and adults suck sap from inflorescence. Honeydew causes sooty mold on flowers.', 'Spray Imidacloprid 0.3ml/L or Deltamethrin 1ml/L at bud emergence. Avoid spray at full bloom.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('d10446cc-3502-147e-5ef8-bc9f67c278ed', 'Banana Weevil / Pseudostem Weevil (केळी भुंगेरा)', 'Entry holes at base of pseudostem. Yellowing and wilting of plants. Internal tunneling.', 'Soil drenching with Chlorpyrifos 20 EC 2ml/L around pseudostem. Use healthy tissue culture plants.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('e21557dd-4613-258f-6f09-cd0f78d389fe', 'Shoot Borer / Rhizome Fly (कंद माशी)', 'Tunneling inside pseudostems. Wilting of infested shoots. Visible entry holes.', 'Spray Acephate 75 SP 600g/100L water. Remove and destroy infested shoots. Neem-based preventive sprays.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('f32668ee-5724-369f-7f1a-de1f89e49aff', 'Shoot Borer (गड माशी)', 'Yellowing and wilting of shoots. Entry holes at base. White larva visible inside stem.', 'Neem Oil 0.5% spray at fortnightly intervals July-October. Remove and destroy affected shoots.');
INSERT INTO pests (crop_master_id, name, symptoms, control_method) VALUES ('043779ff-6835-47af-8f2b-ef2f9af50b00', 'Chilli Thrips (फुलकिडे)', 'Upward curling of leaves silvery streaks. Deformed fruits. Stunted plant growth.', 'Spray Spinosad 2.5 SC 1ml/L or Fipronil 5 SC 1ml/L. Alternate with Neem Oil to prevent resistance.');
